p class="muted">Bestehende Rechnungs-, Zahlungs- und Mahndaten bleiben in dieser Ansicht read-only. Rechnungsdateien werden über den read-only eingebundenen Serverpfad bereitgestellt.</p></div><script>async function copyInvoicePath(button){const path=document.getElementById('invoice-path').innerText.trim();let copied=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(path);copied=true}}catch(e){}if(!copied){const field=document.createElement('textarea');field.value=path;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();try{copied=document.execCommand('copy')}catch(e){}field.remove()}const original='Pfad kopieren';button.textContent=copied?'Pfad kopiert':'Kopieren fehlgeschlagen';setTimeout(()=>button.textContent=original,2000)}</script><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>